import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { createInterface } from 'node:readline';
import { writeFileSync } from 'node:fs';
const { controlledHttp } = await import(pathToFileURL(resolve('tests/fixtures/mcp-http.mjs')).href);
const service = await controlledHttp({ mode: process.argv[1] });
const snapshot = () => ({ requests: service.requests.map(r => ({ method: r.method, rpc: r.message?.method ?? null, responseType: r.responseType ?? null })), calls: service.calls(), sockets: service.sockets.size });
process.stdout.write(JSON.stringify({ ready: true, url: service.url, pid: process.pid, mode: process.argv[1], nonce: process.argv[2] }) + '\n');
process.on('SIGTERM', () => { void service.close().then(() => process.exit(0)); });
for await (const line of createInterface({ input: process.stdin })) {
 if (line === 'snapshot') { const value = snapshot(); writeFileSync(process.argv[3], JSON.stringify(value, null, 2) + '\n', { mode: 0o600 }); process.stdout.write(JSON.stringify(value) + '\n'); }
 else if (line === 'stop') { await service.close(); process.exit(0); }
 else throw new Error('Controlled HTTP operation refused.');
}
